%[text] # Es 01
points_x = [-2 1 2 7];
points_y = [-4 -1 0.5 3];
p = polyfit(points_x, points_y, length(points_x)-1);
x = linspace(min(points_x)-1, max(points_x)+1, 100);
y = polyval(p, x);
plot(x, y, points_x, points_y, "*") %[output:71ef2238]

%%
%[text] ## Es 2
f = @(x) exp(x).*sin(x);
n = 5;
points_x = linspace(-1, 1, n+1);
points_y = f(points_x);
p = polyfit(points_x, points_y, n);
dense_x = linspace(-3, 3, 100);
plot(dense_x, f(dense_x), dense_x, polyval(p, dense_x), "--", points_x, points_y, "o"); %[output:5b880ee8]

%%
%[text] ## Es 3
f = @(x) (x.^2 - 5.*x + 6).*log(x)./x;
a = 1;
b = 4;

for n = 5:5:20 %[output:group:9c52b6de]
    figure(n);
    disp("n = " + n); %[output:86698b30] %[output:63c47c73] %[output:08b25c7b] %[output:5a64290b]
    
    points_x = linspace(a, b, n+1);
    points_y = f(points_x);
    p = polyfit(points_x, points_y, n); %[output:08a27103] %[output:99b7568e]
    
    dense_x = linspace(a, b, 1000);
    
    fy = f(dense_x);
    py = polyval(p, dense_x);
    
    err = max(abs(fy - py));
    disp("Max err: " + err) %[output:7065f2cb] %[output:89edd078] %[output:77a1159f] %[output:6fc025ad]
    
    plot(dense_x, fy, dense_x, py, "--", points_x, points_y, "o"); %[output:868fcc01] %[output:536142e3] %[output:8323a17a] %[output:8f042878]
end %[output:group:9c52b6de]

%%
%[text] ## Es 5
f = @(x) 1./(1+x.^2);
a = -5;
b = 5;


for n = 5:5:20 %[output:group:893299fb]
    c_k = @(k) cos(pi.*(2.*k-1)./(2.*n));
    x_k = @(x) c_k(x).*(b-a)./2 + (a+b)/2;

    figure(n);
    disp("n = " + n); %[output:2503ee2f] %[output:5fc87872] %[output:769dfd6d] %[output:7c3033d2]

    points_x = x_k(1:n);
    points_y = f(points_x);
    p = polyfit(points_x, points_y, n-1);

    dense_x = linspace(a, b, 1000);

    fy = f(dense_x);
    py = polyval(p, dense_x);

    err = max(abs(fy - py));
    disp("Max err: " + err) %[output:2c40879f] %[output:9b7a67d1] %[output:408d78f6] %[output:5a5c591d]

    plot(dense_x, fy, dense_x, py, "--", points_x, points_y, "o"); %[output:2800f859] %[output:9d621e04] %[output:700c1972] %[output:2d804eb9]
end %[output:group:893299fb]
%%
%[text] ## Es 6
f = @(x) 1./(1 + x.^2);

a = -5;
b = 5;

for i=1:3 %[output:group:6109bf26]
    m = 5*(10^(i-1));
    H = 1/m;
    disp("m: " + m + " H: " + H); %[output:04f3a959] %[output:4580485f] %[output:8c3c718e]

    figure(i);
    hold on; %[output:948f6f3f] %[output:5f6b769a] %[output:2020111f]
    
    f_x = linspace(a, b, 10000);
    f_y = f(f_x);
    plot(f_x, f_y, "b");
    
    points_x = linspace(a, b, m);
    points_y = f(points_x);
    plot(points_x, points_y, "y", points_x, points_y, "yO");

    spline = griddedInterpolant(points_x, points_y, "linear");
    max_err = max(abs(f_y - spline(f_x)));
    disp("Max error: " + max_err); %[output:2a743795] %[output:212f821e] %[output:8db5d025]
    
    hold off; %[output:948f6f3f] %[output:5f6b769a] %[output:2020111f]
end %[output:group:6109bf26]


